[
  {
    "id": "meta-description",
    "fix_code": "<meta name=\"description\" content=\"Acme SaaS is the project management platform built for growing teams. Streamline workflows, boost collaboration, and ship projects faster.\">",
    "fix_explanation": "A meta description summarizes the page for search engines and users. Adding this 150-character description improves click-through rates in search results by giving searchers a clear preview of what Acme SaaS offers.",
    "fix_location": "Paste inside the <head> element, directly after the <title> tag."
  },
  {
    "id": "og-title",
    "fix_code": "<meta property=\"og:title\" content=\"Acme SaaS — Project Management for Growing Teams\">",
    "fix_explanation": "The og:title tag controls the headline shown when this page is shared on social platforms like Facebook and LinkedIn. It mirrors the page title so shared links are accurately and attractively labelled.",
    "fix_location": "Paste inside the <head> element, after the meta description tag."
  },
  {
    "id": "og-description",
    "fix_code": "<meta property=\"og:description\" content=\"Acme SaaS is the project management platform built for growing teams. Streamline workflows, boost collaboration, and ship projects faster.\">",
    "fix_explanation": "The og:description tag provides the supporting text shown beneath the title when the page is shared on social media. This improves engagement by giving potential visitors context before they click.",
    "fix_location": "Paste inside the <head> element, directly after the og:title tag."
  },
  {
    "id": "og-image",
    "fix_code": "<meta property=\"og:image\" content=\"https://acme-saas.com/images/og-image.png\">\n<meta property=\"og:image:width\" content=\"1200\">\n<meta property=\"og:image:height\" content=\"630\">\n<meta property=\"og:image:alt\" content=\"Acme SaaS — Project Management for Growing Teams\">",
    "fix_explanation": "The og:image tag defines the preview image displayed when this page is shared on social platforms. Use a 1200x630 px image (PNG or JPG) hosted at the specified URL; replace the path with your actual social share image.",
    "fix_location": "Paste inside the <head> element, directly after the og:description tag."
  },
  {
    "id": "twitter-card",
    "fix_code": "<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Acme SaaS — Project Management for Growing Teams\">\n<meta name=\"twitter:description\" content=\"Acme SaaS is the project management platform built for growing teams. Streamline workflows, boost collaboration, and ship projects faster.\">\n<meta name=\"twitter:image\" content=\"https://acme-saas.com/images/og-image.png\">\n<meta name=\"twitter:image:alt\" content=\"Acme SaaS — Project Management for Growing Teams\">",
    "fix_explanation": "Twitter Card tags control how the page appears when shared on X (Twitter), enabling a rich preview card with a large image, title, and description. The summary_large_image type displays the most prominent and engaging card format.",
    "fix_location": "Paste inside the <head> element, directly after the og:image tags, before the closing </head> tag."
  }
]
